let offlineOnly = true;
try { offlineOnly = localStorage.getItem(offlineKey) !== 'false'; } catch (_) {}
const offlineCheck = overlay.querySelector('#wwis-offline-only');
offlineCheck.checked = offlineOnly;
const applyOfflineOnly = () => { bridge()?.setOfflineOnly?.(offlineOnly); };
offlineCheck.onchange = () => {
  offlineOnly = offlineCheck.checked;
  try { localStorage.setItem(offlineKey, String(offlineOnly)); } catch (_) {}
  applyOfflineOnly();
};
applyOfflineOnly();

// 'auto' (default): generate only while an image server answers; true: never; false: always ask the server
// (a stored 'false' from the old checkbox keeps meaning "generate"; an untouched one becomes auto)
let offlineOnly = 'auto';
try { const v = localStorage.getItem(offlineKey); if (v === 'true' || v === 'false') offlineOnly = v === 'true'; } catch (_) {}
const offlineCheck = overlay.querySelector('#wwis-offline-mode');
const serverNote = overlay.querySelector('#wwis-server');
offlineCheck.value = String(offlineOnly);
const SERVER_NOTE = { ready: '· 그림 서버 연결됨', noengine: '· 그림 서버는 있는데 그림 엔진(ComfyUI 등)이 응답하지 않아요', none: '· 그림 서버 없음' };
const showServer = () => { if (serverNote) serverNote.textContent = SERVER_NOTE[bridge()?.serverState?.() || 'none'] || ''; };
const applyOfflineOnly = () => { bridge()?.setOfflineOnly?.(offlineOnly); showServer(); };
offlineCheck.onchange = () => {
  offlineOnly = offlineCheck.value === 'auto' ? 'auto' : offlineCheck.value === 'true';
  try { localStorage.setItem(offlineKey, String(offlineOnly)); } catch (_) {}
  applyOfflineOnly();
};
applyOfflineOnly();
setInterval(() => { if (overlay.isConnected && overlay.offsetParent !== null) showServer(); }, 3000);   // the game finds the server a little after start
